410	// strictCircuitObject decodes one committed circuit record's own member map,
411	// demanding a JSON object with exactly the known top-level fields once.
412	func strictCircuitObject(raw []byte, what string) (map[string]json.RawMessage, error) {
413		return strictObjectMembers(raw, what, persistCircuitFields)
414	}
415	
416	// strictObjectMembers decodes one committed record's own member map,
417	// demanding a JSON object without repeated keys. A non-nil allowed list
418	// restricts which keys may appear; nil allows any key. It scans only the
419	// record's own level: the envelope scanner already attributes a duplicated
420	// top-level key to this record, and nested values such as the constraint
421	// definition own their (more precise) strict decoders. Keys are compared
422	// after JSON unescaping, so a field repeated through a \uXXXX spelling is
423	// still a duplicate, even when both values are identical.
424	func strictObjectMembers(raw []byte, what string, allowedFields []string) (map[string]json.RawMessage, error) {
425		trimmed := bytes.TrimSpace(raw)
426		if len(trimmed) == 0 || trimmed[0] != '{' {
427			return nil, corruptf("%s must be a JSON object", what)
428		}
429		dec := json.NewDecoder(bytes.NewReader(trimmed))
430		dec.UseNumber()
431		open, err := dec.Token()
432		if err != nil || open != json.Delim('{') {
433			return nil, corruptf("%s must be a JSON object", what)
434		}
435		var allowed map[string]bool
436		if allowedFields != nil {
437			allowed = make(map[string]bool, len(allowedFields))
438			for _, f := range allowedFields {
439				allowed[f] = true
440			}
441		}
442		members := make(map[string]json.RawMessage)
443		for dec.More() {
444			keyTok, err := dec.Token()
445			if err != nil {
446				return nil, corruptf("%s is not valid JSON: %v", what, err)
447			}
448			key, ok := keyTok.(string)
449			if !ok {
450				return nil, corruptf("%s is not valid JSON", what)
451			}
452			if allowed != nil && !allowed[key] {
453				return nil, corruptf("%s has unknown field %q", what, key)
454			}
455			if _, repeated := members[key]; repeated {
456				return nil, corruptf("%s contains duplicate field %q", what, key)
457			}
458			var value json.RawMessage
459			if err := dec.Decode(&value); err != nil {
460				return nil, corruptf("%s is not valid JSON: %v", what, err)
461			}
462			members[key] = value
463		}
464		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
465			return nil, corruptf("%s is not valid JSON", what)
466		}
467		if _, err := dec.Token(); err != io.EOF {
468			return nil, corruptf("%s is not valid JSON: trailing data after the object", what)
469		}
470		return members, nil
471	}
