490	// Strict decoding of the compiled-artifact binding on a committed job record.
491	//
492	// compiled_hash is a field whose presence is meaningful: records written
493	// before bindings existed simply omit it, and an explicit "" is the unbound
494	// state. But once the key appears its value must be a JSON string. A null is
495	// not "no binding" — it is damage to a binding the record claims to carry,
496	// and so is a number, boolean, array or object in its place. Reading either
497	// as the zero string would silently turn a bound job into an unbound one
498	// (and the next commit would drop the field entirely), so the read is
499	// refused as data corruption instead. A repeated key — including one
500	// repeated through JSON string escapes, even with identical values — is
501	// likewise refused rather than resolved to its last value. A legal non-empty
502	// string keeps being matched against the pinned version's artifact by
503	// validateEnvelope, exactly as written.
504	//
505	// Only the binding field is judged here; every other field keeps the
506	// ordinary struct decoding.
507	func (j *persistJob) UnmarshalJSON(raw []byte) error {
508		const what = "stored job record"
509		if string(bytes.TrimSpace(raw)) == "null" {
510			return corruptf("%s must be a JSON object, not null", what)
511		}
512		members, err := strictObjectMembers(raw, what, nil)
513		if err != nil {
514			return err
515		}
516		// Name the job in a binding-field failure when its id is legible; the id
517		// itself is decoded for real by the ordinary pass below.
518		where := what
519		if idRaw, ok := members["id"]; ok {
520			if id, idErr := storedRecordShape.string(idRaw, what+` field "id"`); idErr == nil {
521				where = fmt.Sprintf("stored job record %q", id)
522			}
523		}
524		compiledHash := ""
525		hasBinding := false
526		if hashRaw, present := members["compiled_hash"]; present {
527			hash, err := storedRecordShape.string(hashRaw, where+` field "compiled_hash"`)
528			if err != nil {
529				return err
530			}
531			compiledHash, hasBinding = hash, true
532		}
533		type plainJob persistJob
534		var decoded plainJob
535		if err := json.Unmarshal(raw, &decoded); err != nil {
536			return corruptf("%s is not valid JSON: %v", what, err)
537		}
538		if hasBinding {
539			decoded.CompiledHash = compiledHash
540		}
541		*j = persistJob(decoded)
542		return nil
543	}
