545	// Store is a persistent workbench backed by one local data directory.
546	//
547	// All operations are safe for concurrent use by multiple goroutines and by
548	// several processes pointed at the same directory: an in-process mutex plus a
549	// process-shared flock serialize commits, and every commit is an atomic
550	// temp-file/fsync/rename replacement. Open the directory with Open and call
551	// Close when done.
552	type Store struct {
553		dir  string
554		mu   sync.Mutex
555		lock *os.File
556	
557		data envelope
558	}
559	
560	// Open opens (creating if needed) the workbench data in dir. If the
561	// directory does not exist it is created. Existing committed data is loaded
562	// and fully validated before Open returns; on a corrupt, truncated or
563	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
564	// leaves every file in the directory untouched.
565	func Open(dir string) (*Store, error) {
566		if dir == "" {
567			return nil, invalidf("data directory must not be empty")
568		}
569		if err := os.MkdirAll(dir, 0o755); err != nil {
570			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
571		}
572		lockPath := filepath.Join(dir, dirLockFile)
573		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
574		if err != nil {
575			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
576		}
577		// Serialize against other processes while we read / validate.
578		if err := lockExclusive(lock); err != nil {
579			lock.Close()
580			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
581		}
582	
583		s := &Store{dir: dir, lock: lock}
584		if err := s.loadLocked(); err != nil {
585			unlockLock(lock)
586			lock.Close()
587			return nil, err
588		}
589		// The lock is taken again per operation; holding it for the store's
590		// lifetime would forbid two open handles on one directory.
591		if err := unlockLock(lock); err != nil {
592			lock.Close()
593			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
594		}
595		return s, nil
596	}
597	
598	// Close releases the directory lock. It does not discard committed data.
599	func (s *Store) Close() error {
600		s.mu.Lock()
601		defer s.mu.Unlock()
602		if s.lock == nil {
603			return nil
604		}
605		var first error
606		if err := unlockLock(s.lock); err != nil {
607			first = err
608		}
609		if err := s.lock.Close(); err != nil && first == nil {
610			first = err
611		}
612		s.lock = nil
613		return first
614	}
615	
616	// Dir reports the data directory backing the store.
617	func (s *Store) Dir() string { return s.dir }
618	
619	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
620	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
621	
622	// loadLocked reads and validates the committed file. Caller must hold the
623	// exclusive flock; the in-process mutex is taken by the public Open path.
624	func (s *Store) loadLocked() error {
625		raw, err := os.ReadFile(s.dataPath())
626		if errors.Is(err, os.ErrNotExist) {
627			s.data = envelope{Format: FormatVersion}
628			return nil
629		}
630		if err != nil {
631			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
632		}
633		if len(strings.TrimSpace(string(raw))) == 0 {
634			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
635		}
636	
637		var env envelope
638		if err := json.Unmarshal(raw, &env); err != nil {
639			// Shape failures surfaced by the persisted-definition decoders are
640			// integrity failures, not JSON syntax errors; report their detail
641			// instead of the generic "not valid JSON" wording.
642			var se StoreError
643			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
644				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
645			}
646			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
647		}
648		if env.Format == 0 {
649			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
650		}
651		if env.Format != FormatVersion {
652			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
653				s.dataPath(), env.Format, FormatVersion)
654		}
655		if err := validateEnvelope(env); err != nil {
656			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
657		}
658		s.data = env
659		return nil
660	}
661	
662	// commitLocked writes the pending state atomically: temp file → fsync →
663	// rename → fsync directory. Caller must hold both the in-process mutex and
664	// the exclusive flock; all in-memory mutations must already have happened and
665	// been rule-checked, so a failure here occurs before any success is reported.
666	func (s *Store) commitLocked() error {
667		s.data.Format = FormatVersion
668		// Stable output: records are stored sorted so files are deterministic.
669		sortEnvelope(&s.data)
670	
671		payload, err := json.MarshalIndent(&s.data, "", "  ")
672		if err != nil {
673			return fmt.Errorf("cannot encode data: %w", err)
674		}
675		payload = append(payload, '\n')
676	
677		tmp := s.tmpPath()
678		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
679		if err != nil {
680			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
681		}
682		if _, err := f.Write(payload); err != nil {
683			f.Close()
684			os.Remove(tmp)
685			return fmt.Errorf("cannot write staged data: %w", err)
686		}
687		if err := f.Sync(); err != nil {
688			f.Close()
689			os.Remove(tmp)
690			return fmt.Errorf("cannot flush staged data: %w", err)
691		}
692		if err := f.Close(); err != nil {
693			os.Remove(tmp)
694			return fmt.Errorf("cannot finish staged data: %w", err)
695		}
696		if err := os.Rename(tmp, s.dataPath()); err != nil {
697			os.Remove(tmp)
698			return fmt.Errorf("cannot commit data file: %w", err)
699		}
700		if err := syncDir(s.dir); err != nil {
701			// The rename already happened; lack of dir fsync only weakens crash
702			// durability, never correctness of what is visible now.
703			return nil
704		}
705		return nil
706	}
707	
708	// withLock runs fn under the in-process mutex and an exclusive flock, then
709	// atomically commits when fn requests it. The on-disk state is re-read after
710	// acquiring the lock, so concurrent commits from another process or another
711	// handle are always observed. Operations validate before mutating; a rejected
712	// operation (commit=false or an error) writes nothing and leaves committed
713	// state unchanged.
714	func (s *Store) withLock(fn func() (commit bool, err error)) error {
715		s.mu.Lock()
716		defer s.mu.Unlock()
717		if s.lock == nil {
718			return invalidf("store is closed")
719		}
720		if err := lockExclusive(s.lock); err != nil {
721			return fmt.Errorf("cannot lock data directory: %w", err)
722		}
723		defer unlockLock(s.lock)
724	
725		if err := s.loadLocked(); err != nil {
726			return err
727		}
728		commit, err := fn()
729		if err != nil {
730			return err
731		}
732		if !commit {
733			return nil
734		}
735		return s.commitLocked()
736	}
737	
738	// withLockRead runs fn under a shared flock over freshly reloaded state.
739	func (s *Store) withLockRead(fn func() error) error {
740		s.mu.Lock()
741		defer s.mu.Unlock()
742		if s.lock == nil {
743			return invalidf("store is closed")
744		}
745		if err := lockShared(s.lock); err != nil {
746			return fmt.Errorf("cannot lock data directory: %w", err)
747		}
748		defer unlockLock(s.lock)
749		if err := s.loadLocked(); err != nil {
750			return err
751		}
752		return fn()
753	}
754	
755	func sortEnvelope(env *envelope) {
756		sort.Slice(env.Circuits, func(i, j int) bool {
757			if env.Circuits[i].Name != env.Circuits[j].Name {
758				return env.Circuits[i].Name < env.Circuits[j].Name
759			}
760			return env.Circuits[i].Version < env.Circuits[j].Version
761		})
762		sort.Slice(env.Setups, func(i, j int) bool {
763			if env.Setups[i].Name != env.Setups[j].Name {
764				return env.Setups[i].Name < env.Setups[j].Name
765			}
766			return env.Setups[i].Version < env.Setups[j].Version
767		})
768		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
769		sort.Slice(env.Artifacts, func(i, j int) bool {
770			if env.Artifacts[i].Name != env.Artifacts[j].Name {
771				return env.Artifacts[i].Name < env.Artifacts[j].Name
772			}
773			return env.Artifacts[i].Version < env.Artifacts[j].Version
774		})
775	}
776	
777	// validateEnvelope re-checks every invariant on load so a tampered or
778	// hand-edited file cannot bypass the domain rules.
779	func validateEnvelope(env envelope) error {
780		seenCircuit := make(map[[2]string]bool)
781		circuitOK := make(map[[2]string]bool)
782		for i, c := range env.Circuits {
783			key := [2]string{c.Name, itoa(c.Version)}
784			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
785				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
786			}
787			if c.Version <= 0 {
788				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
789			}
790			if seenCircuit[key] {
791				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
792			}
793			seenCircuit[key] = true
794			if c.Constraints <= 0 {
795				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
796			}
797			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
798				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
799			}
800			// The same representability rule the write path enforces: wire 0 plus
801			// every declared input must fit inside the platform's int. A record
802			// beyond that bound can never have been written by this build and
803			// cannot be checked safely, so the directory is corrupt rather than
804			// silently narrowed or read with a wrapped-around layout.
805			if !inputLayoutRepresentable(c.PublicInputs, c.PrivateInputs) {
806				return fmt.Errorf("circuit %q v%d: input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
807					c.Name, c.Version, c.PublicInputs, c.PrivateInputs, maxInputWires)
808			}
809			if c.Definition != nil {
810				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
811					return err
812				}
813			}
814			circuitOK[key] = true
815		}
816		seenSetup := make(map[[2]string]bool)
817		for i, p := range env.Setups {
818			key := [2]string{p.Name, itoa(p.Version)}
819			if !circuitOK[key] {
820				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
821			}
822			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
823			if c == nil || !c.Frozen {
824				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
825			}
826			if seenSetup[key] {
827				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
828			}
829			seenSetup[key] = true
830		}
831		seenJob := make(map[string]bool)
832		for i, j := range env.Jobs {
833			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
834				return fmt.Errorf("job #%d has an empty or blank id", i+1)
835			}
836			if seenJob[j.ID] {
837				return fmt.Errorf("job %q appears more than once", j.ID)
838			}
839			seenJob[j.ID] = true
840			if j.Kind != "prove" {
841				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
842			}
843			if j.Attempt <= 0 {
844				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
845			}
846			key := [2]string{j.Circuit, itoa(j.Version)}
847			if !circuitOK[key] {
848				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
849			}
850			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
851			if c == nil || !c.Frozen {
852				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
853			}
854			if !seenSetup[key] {
855				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
856			}
857			// A recorded compiled-artifact binding must still resolve against the
858			// pinned version's artifact; a dangling or mismatched binding makes
859			// the file unreadable rather than silently dropping the binding.
860			if j.CompiledHash != "" {
861				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
862				if artifact == nil {
863					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
864				}
865				if artifact.Hash != j.CompiledHash {
866					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
867						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
868				}
869			}
870		}
871		seenArtifact := make(map[[2]string]bool)
872		for i, a := range env.Artifacts {
873			key := [2]string{a.Name, itoa(a.Version)}
874			if !circuitOK[key] {
875				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
876			}
877			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
878			if c == nil || !c.Frozen {
879				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
880			}
881			if seenArtifact[key] {
882				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
883			}
884			seenArtifact[key] = true
885			if c.Definition == nil {
886				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
887			}
888			if a.Constraints != c.Constraints {
889				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
890					a.Name, a.Version, a.Constraints, c.Constraints)
891			}
892			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
893			if err != nil {
894				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
895			}
896			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
897				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
898			}
899			wantHash := artifactHash(a.Name, a.Version, def)
900			if a.Hash != wantHash {
901				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
902					a.Name, a.Version, a.Hash, wantHash)
903			}
904		}
905		return nil
906	}
907	
908	// validatePersistDefinition re-validates a stored definition against its
909	// version's declared counts: prime modulus, in-range wires and an exact
910	// constraint count match.
911	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
912		parsed, err := definitionFromPersist(*def, public, private)
913		if err != nil {
914			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
915		}
916		if !parsed.compatibleWith(constraints, public, private) {
917			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
918		}
919		return nil
920	}
921	
922	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
923		for i := range cs {
924			if cs[i].Name == name && cs[i].Version == version {
925				return &cs[i]
926			}
927		}
928		return nil
929	}
930	
931	func itoa(v int) string { return fmt.Sprintf("%d", v) }
932

