294	// The binding belongs to the job id. Identical resubmits are idempotent;
295	// changing or removing the hash, or adding one to a previously unbound job,
296	// is ErrConflict with the stored job preserved. The existing-id conflict is
297	// reported before the new request's artifact is validated.
298	func TestSubmitJobBindingConflictPreservesStoredJob(t *testing.T) {
299		cases := []struct {
300			name string
301			// run seeds a fresh store, submits the original job and returns it
302			// together with the conflicting resubmission.
303			run func(t *testing.T, s *Store) (original, conflict Job)
304		}{
305			{
306				name: "changed hash conflicts",
307				run: func(t *testing.T, s *Store) (Job, Job) {
308					h1 := compiledVersion(t, s, "c", 1, validDef)
309					h2 := compiledVersion(t, s, "c", 2, validDef)
310					original := boundProveJob("j", "c", 1, h1)
311					if _, err := s.SubmitJob(original); err != nil {
312						t.Fatal(err)
313					}
314					return original, boundProveJob("j", "c", 1, h2)
315				},
316			},
317			{
318				name: "removed hash conflicts",
319				run: func(t *testing.T, s *Store) (Job, Job) {
320					h1 := compiledVersion(t, s, "c", 1, validDef)
321					original := boundProveJob("j", "c", 1, h1)
322					if _, err := s.SubmitJob(original); err != nil {
323						t.Fatal(err)
324					}
325					return original, boundProveJob("j", "c", 1, "")
326				},
327			},
328			{
329				name: "adding hash to unbound job conflicts",
330				run: func(t *testing.T, s *Store) (Job, Job) {
331					h1 := compiledVersion(t, s, "c", 1, validDef)
332					original := boundProveJob("j", "c", 1, "")
333					if _, err := s.SubmitJob(original); err != nil {
334						t.Fatal(err)
335					}
336					return original, boundProveJob("j", "c", 1, h1)
337				},
338			},
339			{
340				name: "conflict precedes artifact mismatch",
341				run: func(t *testing.T, s *Store) (Job, Job) {
342					h1 := compiledVersion(t, s, "c", 1, validDef)
343					original := boundProveJob("j", "c", 1, h1)
344					if _, err := s.SubmitJob(original); err != nil {
345						t.Fatal(err)
346					}
347					// Sanity: for a fresh id this foreign hash is a real mismatch…
348					if _, err := s.SubmitJob(boundProveJob("fresh-id", "c", 1, "foreign-hash")); !errors.Is(err, ErrArtifactMismatch) {
349						t.Fatalf("sanity mismatch: %v", err)
350					}
351					// …but for the existing id the conflict is reported first.
352					return original, boundProveJob("j", "c", 1, "foreign-hash")
353				},
354			},
355			{
356				name: "conflict precedes artifact missing",
357				run: func(t *testing.T, s *Store) (Job, Job) {
358					h1 := compiledVersion(t, s, "c", 1, validDef)
359					// A frozen version with a setup but no artifact: a fresh id with
360					// any non-empty hash hits ErrArtifactMissing…
361					frozenSetupUncompiled(t, s, "d", 1)
362					original := boundProveJob("j", "c", 1, h1)
363					if _, err := s.SubmitJob(original); err != nil {
364						t.Fatal(err)
365					}
366					if _, err := s.SubmitJob(boundProveJob("fresh-id", "d", 1, "any-hash")); !errors.Is(err, ErrArtifactMissing) {
367						t.Fatalf("sanity missing: %v", err)
368					}
369					// …repurposing the existing id is a conflict first, not a new
370					// binding failure against "d" v1.
371					return original, boundProveJob("j", "d", 1, "any-hash")
372				},
373			},
374		}
375		for _, tc := range cases {
376			t.Run(tc.name, func(t *testing.T) {
377				s := openTestStore(t)
378				original, conflictReq := tc.run(t, s)
379	
380				if _, err := s.SubmitJob(conflictReq); !errors.Is(err, ErrConflict) {
381					t.Fatalf("want conflict, got %v", err)
382				}
383				got, err := s.GetJob("j")
384				if err != nil {
385					t.Fatal(err)
386				}
387				if got != original {
388					t.Fatalf("stored job changed after conflict:\n got %+v\nwant %+v", got, original)
389				}
390				jobs, _ := s.ListJobs()
391				// The sanity-check fresh ids were refused and stored nothing, so the
392				// conflict leaves exactly the original job.
393				if len(jobs) != 1 {
394					t.Fatalf("want exactly one job, got %+v", jobs)
395				}
396	
397				// The identical original request still returns the same record.
398				again, err := s.SubmitJob(original)
399				if err != nil || again != original {
400					t.Fatalf("identical resubmit after conflict: %+v %v", again, err)
401				}
402			})
403		}
404	}
405	
406	// An empty hash means unbound for the job's whole life: it is accepted on a
407	// not-yet-compiled version without compiling it, a later compilation never
408	// backfills the hash, an already-compiled target never auto-selects its
409	// artifact, counts-only versions keep their register-only ability, and no
410	// setup is auto-registered.
411	func TestEmptyHashLeavesJobUnbound(t *testing.T) {
412		t.Run("uncompiled version does not compile or bind", func(t *testing.T) {
413			dir := t.TempDir()
414			s, err := Open(dir)
415			if err != nil {
416				t.Fatal(err)
417			}
418			frozenSetupUncompiled(t, s, "c", 1)
419			req := boundProveJob("ju", "c", 1, "")
420			stored, err := s.SubmitJob(req)
421			if err != nil {
422				t.Fatalf("register-only submit: %v", err)
423			}
424			if stored != req || stored.CompiledHash != "" {
425				t.Fatalf("unbound job stored a binding: %+v", stored)
426			}
427			// Submission must not have compiled the version on the side.
428			if _, err := s.GetArtifact("c", 1); !errors.Is(err, ErrArtifactMissing) {
429				t.Fatalf("submit auto-compiled the version: %v", err)
430			}
431			// Compiling afterwards never backfills the old job's binding.
432			a, err := s.CompileCircuit("c", 1)
433			if err != nil {
434				t.Fatal(err)
435			}
436			got, _ := s.GetJob("ju")
437			if got.CompiledHash != "" {
438				t.Fatalf("later compilation backfilled the hash: %+v", got)
439			}
440			if err := s.Close(); err != nil {
441				t.Fatal(err)
442			}
443			s2, err := Open(dir)
444			if err != nil {
445				t.Fatal(err)
446			}
447			defer s2.Close()
448			got, _ = s2.GetJob("ju")
449			if got.CompiledHash != "" {
450				t.Fatalf("empty binding did not survive reopen: %+v", got)
451			}
452			if a2, err := s2.GetArtifact("c", 1); err != nil || a2.Hash != a.Hash {
453				t.Fatalf("compiled artifact state after reopen: %+v %v", a2, err)
454			}
455		})
456	
457		t.Run("compiled version does not auto-select artifact", func(t *testing.T) {
458			s := openTestStore(t)
459			h := compiledVersion(t, s, "c", 1, validDef)
460			stored, err := s.SubmitJob(boundProveJob("ju", "c", 1, ""))
461			if err != nil {
462				t.Fatalf("unbound submit against compiled version: %v", err)
463			}
464			if stored.CompiledHash != "" {
465				t.Fatalf("empty hash auto-bound to %q", stored.CompiledHash)
466			}
467			got, _ := s.GetJob("ju")
468			if got.CompiledHash != "" {
469				t.Fatalf("queried unbound job carries the artifact hash: %+v", got)
470			}
471			// A sibling explicit binding on the same version still works and stays
472			// distinct.
473			bound, err := s.SubmitJob(boundProveJob("jb", "c", 1, h))
474			if err != nil {
475				t.Fatal(err)
476			}
477			if bound.CompiledHash != h {
478				t.Fatalf("explicit binding wrong: %+v", bound)
479			}
480			jobs, _ := s.ListJobs()
481			if len(jobs) != 2 {
482				t.Fatalf("want 2 jobs, got %+v", jobs)
483			}
484			for _, j := range jobs {
485				want := h
486				if j.ID == "ju" {
487					want = ""
488				}
489				if j.CompiledHash != want {
490					t.Fatalf("job %q hash = %q, want %q", j.ID, j.CompiledHash, want)
491				}
492			}
493		})
494	
495		t.Run("counts-only version keeps register-only ability", func(t *testing.T) {
496			s := openTestStore(t)
497			readyCircuit(t, s, "bare", 1)
498			stored, err := s.SubmitJob(boundProveJob("jb", "bare", 1, ""))
499			if err != nil {
500				t.Fatalf("counts-only register-only submit: %v", err)
501			}
502			if stored.CompiledHash != "" {
503				t.Fatalf("counts-only job carries a hash: %+v", stored)
504			}
505			// This version can never compile (no definition imported); the job
506			// remains valid and unbound.
507			if _, err := s.CompileCircuit("bare", 1); !errors.Is(err, ErrDefinitionMissing) {
508				t.Fatalf("want definition missing, got %v", err)
509			}
510			got, err := s.GetJob("jb")
511			if err != nil || got != stored {
512				t.Fatalf("counts-only job after failed compile: %+v %v", got, err)
513			}
514		})
515	
516		t.Run("missing setup is not auto-registered even with empty hash", func(t *testing.T) {
517			s := openTestStore(t)
518			// Frozen and compiled, but deliberately no trusted setup.
519			seedDraftWithDef(t, s, "ns", 1, 1, 1, validDef)
520			if _, err := s.FreezeCircuit("ns", 1); err != nil {
521				t.Fatal(err)
522			}
523			if _, err := s.CompileCircuit("ns", 1); err != nil {
524				t.Fatal(err)
525			}
526			if _, err := s.SubmitJob(boundProveJob("jx", "ns", 1, "")); !errors.Is(err, ErrSetupMissing) {
527				t.Fatalf("want trusted setup missing, got %v", err)
528			}
529			if _, found, err := s.GetSetup("ns", 1); err != nil || found {
530				t.Fatalf("submit auto-registered a setup: found=%v err=%v", found, err)
531			}
532			if _, err := s.GetJob("jx"); !errors.Is(err, ErrNotFound) {
533				t.Fatalf("refused job left a record: %v", err)
534			}
535		})
536	}
