package zkcircuit

import (
	"errors"
	"strings"
	"testing"
)

// Scratch verification for case-variant compiled_hash handling (task fix).
func TestScratchCaseVariantBinding(t *testing.T) {
	replaceField := func(t *testing.T, dir, hash, replacement string) string {
		valid, err := readDataFile(t, dir)
		if err != nil {
			t.Fatal(err)
		}
		field := `"compiled_hash": "` + hash + `"`
		bad := strings.Replace(string(valid), field, replacement, 1)
		if bad == string(valid) {
			t.Fatalf("field not found in %s", valid)
		}
		writeDataFile(t, dir, []byte(bad))
		return bad
	}

	t.Run("uppercase null is corrupt", func(t *testing.T) {
		dir, h := seedBoundJobStore(t)
		bad := replaceField(t, dir, h, `"COMPILED_HASH": null`)
		_, err := Open(dir)
		if !errors.Is(err, ErrDataCorrupt) {
			t.Fatalf("want corrupt, got %v", err)
		}
		if !strings.Contains(err.Error(), `"j-bound"`) || !strings.Contains(err.Error(), "compiled_hash") {
			t.Fatalf("error must name job and field: %v", err)
		}
		got, _ := readDataFile(t, dir)
		if string(got) != bad {
			t.Fatal("file modified")
		}
	})

	t.Run("uppercase non-string shapes are corrupt", func(t *testing.T) {
		for _, v := range []string{"5", "true", `["x"]`, `{"h":"x"}`} {
			dir, h := seedBoundJobStore(t)
			replaceField(t, dir, h, `"Compiled_Hash": `+v)
			if _, err := Open(dir); !errors.Is(err, ErrDataCorrupt) {
				t.Fatalf("value %s: want corrupt, got %v", v, err)
			}
		}
	})

	t.Run("single uppercase valid string keeps binding", func(t *testing.T) {
		dir, h := seedBoundJobStore(t)
		replaceField(t, dir, h, `"COMPILED_HASH": "`+h+`"`)
		s, err := Open(dir)
		if err != nil {
			t.Fatalf("valid uppercase binding must load: %v", err)
		}
		defer s.Close()
		got, err := s.GetJob("j-bound")
		if err != nil {
			t.Fatal(err)
		}
		if got.CompiledHash != h {
			t.Fatalf("binding lost: %q", got.CompiledHash)
		}
	})

	t.Run("mixed-case valid string keeps binding", func(t *testing.T) {
		dir, h := seedBoundJobStore(t)
		replaceField(t, dir, h, `"Compiled_Hash": "`+h+`"`)
		s, err := Open(dir)
		if err != nil {
			t.Fatalf("valid mixed-case binding must load: %v", err)
		}
		defer s.Close()
		got, _ := s.GetJob("j-bound")
		if got.CompiledHash != h {
			t.Fatalf("binding lost: %q", got.CompiledHash)
		}
	})

	t.Run("uppercase explicit empty stays unbound", func(t *testing.T) {
		dir, h := seedBoundJobStore(t)
		replaceField(t, dir, h, `"COMPILED_HASH": ""`)
		s, err := Open(dir)
		if err != nil {
			t.Fatalf("empty uppercase binding must load: %v", err)
		}
		defer s.Close()
		got, _ := s.GetJob("j-bound")
		if got.CompiledHash != "" {
			t.Fatalf("read as bound: %+v", got)
		}
	})

	t.Run("lower plus upper identical values rejected", func(t *testing.T) {
		dir, h := seedBoundJobStore(t)
		replaceField(t, dir, h, `"compiled_hash": "`+h+`", "COMPILED_HASH": "`+h+`"`)
		_, err := Open(dir)
		if !errors.Is(err, ErrDataCorrupt) {
			t.Fatalf("want corrupt, got %v", err)
		}
		if !strings.Contains(err.Error(), `"j-bound"`) || !strings.Contains(err.Error(), "compiled_hash") {
			t.Fatalf("error must name job and field: %v", err)
		}
	})

	t.Run("upper then lower order also rejected", func(t *testing.T) {
		dir, h := seedBoundJobStore(t)
		replaceField(t, dir, h, `"COMPILED_HASH": "`+h+`", "compiled_hash": "`+h+`"`)
		if _, err := Open(dir); !errors.Is(err, ErrDataCorrupt) {
			t.Fatalf("want corrupt, got %v", err)
		}
	})

	t.Run("escaped uppercase spelling behaves the same", func(t *testing.T) {
		dir, h := seedBoundJobStore(t)
		replaceField(t, dir, h, `"COMPILED_HASH": "`+h+`"`)
		s, err := Open(dir)
		if err != nil {
			t.Fatalf("escaped uppercase binding must load: %v", err)
		}
		defer s.Close()
		got, _ := s.GetJob("j-bound")
		if got.CompiledHash != h {
			t.Fatalf("binding lost: %q", got.CompiledHash)
		}
	})

	t.Run("escaped duplicate of variant rejected", func(t *testing.T) {
		dir, h := seedBoundJobStore(t)
		replaceField(t, dir, h, `"compiled_hash": "`+h+`", "COMPILED_HASH": "`+h+`"`)
		if _, err := Open(dir); !errors.Is(err, ErrDataCorrupt) {
			t.Fatalf("want corrupt, got %v", err)
		}
	})

	t.Run("wrong hash via variant key still mismatches", func(t *testing.T) {
		dir, h := seedBoundJobStore(t)
		replaceField(t, dir, h, `"COMPILED_HASH": "deadbeef"`)
		if _, err := Open(dir); !errors.Is(err, ErrDataCorrupt) {
			t.Fatalf("want corrupt (dangling binding), got %v", err)
		}
	})
}

